const BUDGET_CATEGORIES = { FOOD:'飲食', CLOTHING_DAILY:'衣著日用', HOUSING:'居住', TRANSPORT:'交通', HEALTHCARE:'醫療健康', INSURANCE_TAX:'保險稅務', LEARNING:'學習成長', LEISURE:'休閒娛樂', FAMILY_SOCIAL:'家庭人情', REPLACEMENT:'耐用品汰換', OTHER:'其他' };
